});

const items = $('merge_branches').all().map((i) => i.json);
const req = $('normalize_input').first().json;
const errors = items.filter((i) => i.ERROR).map((i) => i.ASSET_TYPE + ': ' + i.ERROR);
const payload = items.map((i) => Object.assign({}, i, {
  SPEC: undefined, MARKUP: i.CONTENT_TYPE === 'image/svg+xml' ? i.MARKUP : undefined,
}));
return [{ json: {
  RUN_ID: req.RUN_ID,
  STATUS: errors.length === 0 ? 'COMPLETE' : (items.some((i) => !i.ERROR) ? 'PARTIAL' : 'FAILED'),
  REQUEST: JSON.stringify({ ASSET_TYPES: req.ASSET_TYPES, FEEDBACK: req.FEEDBACK,
