const a = $('capture_frames').first().json;
const out = $input.first().json || {};
const base = {
  ASSET_TYPE: a.ASSET_TYPE, RENDER_MODE: a.RENDER_MODE || '', FORMAT: a.FORMAT || '',
  STATUS: '', SPEC_JSON: a.SPEC_JSON || '', PROMPT: '', CONTENT_TYPE: '', ERROR: '',
  DURATION_MS: a.DURATION_MS || '', FRAME_COUNT: a.FRAME_COUNT || '',
  WIDTH: a.WIDTH || '', HEIGHT: a.HEIGHT || '', MARKUP: '', IMAGE: '',
};
const img = String(out.stdout || '').trim();
if (out.error || !/^data:image\/[a-z+.-]+;base64,/.test(img)) {
  const reason = String(out.error || out.stderr || 'animation assembly failed').slice(0, 500);
  return [{ json: Object.assign({}, base, { STATUS: 'ERROR', ERROR: reason }) }];
}
return [{ json: Object.assign({}, base, {
  STATUS: 'RENDERED', IMAGE: img, CONTENT_TYPE: img.slice(5, img.indexOf(';')),
}) }];

const a = $('capture_frames').first().json;
const frames = Math.max(1, Math.min(36, Number(a.FRAME_COUNT) || 36));
const duration = Math.max(1000, Math.min(20000, Number(a.DURATION_MS) || 3000));
const run = String(a.RUN_ID);
const asset = String(a.ASSET_TYPE);
if (!/^[A-Za-z0-9_-]+$/.test(run)) throw new Error('unsafe RUN_ID');
if (!/^[a-z0-9_]+$/.test(asset)) throw new Error('unsafe ASSET_TYPE');
const dir = '/home/node/.n8n-files/' + run + '/' + asset;
const img2webp = '/usr/local/lib/node_modules/webp-converter/bin/libwebp_linux/bin/img2webp';
const name = (i) => 'f_' + String(i).padStart(3, '0') + '.jpg';
// Both encoders get the whole duration: WebP in milliseconds, GIF in centiseconds,
// spreading the remainder over the last frames so the total is exact rather than
// rounded per frame (3000 ms over 24 frames is 12x12cs + 12x13cs, not 24x13cs).
const webpArgs = [];
const wBase = Math.floor(duration / frames);
const wRem = duration - wBase * frames;
const gifArgs = [];
const totalCs = Math.max(frames, Math.round(duration / 10));
const gBase = Math.floor(totalCs / frames);
const gRem = totalCs - gBase * frames;
for (let i = 0; i < frames; i++) {
  webpArgs.push('-d', String(wBase + (i >= frames - wRem ? 1 : 0)), name(i));
  gifArgs.push('-delay', String(gBase + (i >= frames - gRem ? 1 : 0)), name(i));
}
// The type's declared format picks the encoder and the other one is the fallback, so a
// gif type is assembled as GIF rather than falling back to it. A missing FORMAT keeps
// the original webp-then-gif order.
const webpCmd = "'" + img2webp + "' -loop 0 " + webpArgs.join(' ') + " -o out.webp";
const gifCmd = 'gm convert ' + gifArgs.join(' ') + ' out.gif';
const encoders = {
  gif: { want: gifCmd, F: 'out.gif', MIME: 'image/gif', other: webpCmd, oF: 'out.webp', oMIME: 'image/webp' },
  webp: { want: webpCmd, F: 'out.webp', MIME: 'image/webp', other: gifCmd, oF: 'out.gif', oMIME: 'image/gif' },
};
const pick = encoders[String(a.FORMAT || '').toLowerCase()] || encoders.webp;
const encoderCmd = [
  'if ' + pick.want + ' >/dev/null 2>&1; then F=' + pick.F + '; MIME=' + pick.MIME + ';',
  'elif ' + pick.other + ' >/dev/null 2>&1; then F=' + pick.oF + '; MIME=' + pick.oMIME + ';',
  'else exit 1; fi',
].join(' ');
const cmd = [
  'set -e',
  "cd '" + dir + "'",
  encoderCmd,
  "printf 'data:%s;base64,' \"$MIME\"",
  'base64 -w0 "$F"',
  "rm -rf '" + dir + "'",
  "rmdir '/home/node/.n8n-files/" + run + "' 2>/dev/null || true",
].join('\n');
return [{ json: { CMD: cmd, RUN_ID: run, ASSET_TYPE: asset } }];

const a = $('if_animated').first().json;
const err = $input.first().json || {};
const reason = err.CAPTURE_ERROR || err.error || 'frame capture failed';
return [{ json: Object.assign({}, a, {
  STATUS: 'ERROR',
  ERROR: String(reason).slice(0, 500),
  MARKUP: '', IMAGE: '', CONTENT_TYPE: '',
  DURATION_MS: '', FRAME_COUNT: '', WIDTH: '', HEIGHT: '',
