const a = $('if_animated').first().json;
const bail = (msg) => [{ json: Object.assign({}, a, {
  CAPTURE_ERROR: String(msg).slice(0, 500), WIDTH: '', FRAME_COUNT: '', HEIGHT: '',
}) }];
try {
  const markup = a.MARKUP || '';
  if (!markup) throw new Error('no markup to capture for ' + (a.ASSET_TYPE || 'asset'));
  const duration = Math.max(1000, Math.min(20000, Number(a.DURATION_MS) || 3000));
  const frames = Math.max(1, Math.min(36, Number(a.FRAME_COUNT) || 36));
  const viewport = Math.max(1, Math.min(1200, Number(a.VIEWPORT) || 1200));
  const aspect = String(a.ASPECT || '4:5').split(':');
  const rw = Number(aspect[0]) || 4;
  const rh = Number(aspect[1]) || 5;
  const width = Math.round(viewport);
  const height = Math.round((viewport * rh) / rw);
  if (!/^[A-Za-z0-9_-]+$/.test(String(a.RUN_ID))) throw new Error('unsafe RUN_ID');
  if (!/^[a-z0-9_]+$/.test(String(a.ASSET_TYPE))) throw new Error('unsafe ASSET_TYPE');
  const dir = '/home/node/.n8n-files/' + a.RUN_ID + '/' + a.ASSET_TYPE;
  await $page.setViewport({ width, height, deviceScaleFactor: 1 });
  await $page.goto('data:text/html;charset=utf-8,' + encodeURIComponent(markup), { waitUntil: 'load', timeout: 60000 });
  await $page.evaluate(() => document.fonts.ready);
  await $page.evaluate(() => { document.getAnimations().forEach((an) => { an.pause(); an.currentTime = 0; }); });
  for (let i = 0; i < frames; i++) {
    const t = (i * duration) / frames;
    await $page.evaluate((at) => { document.getAnimations().forEach((an) => { an.currentTime = at; }); }, t);
    await $page.evaluate(() => new Promise((done) => requestAnimationFrame(() => requestAnimationFrame(done))));
    await $page.screenshot({ type: 'jpeg', quality: 85, path: dir + '/f_' + String(i).padStart(3, '0') + '.jpg' });
  }
  return [{ json: Object.assign({}, a, { WIDTH: String(width), HEIGHT: String(height), FRAME_COUNT: String(frames), DURATION_MS: String(duration) }) }];
} catch (e) {
  return bail(e && e.message ? e.message : e);
}

