// Shape the render-service request from the asset: the spec travels as JSON and
// nothing executable crosses the boundary. Compute the frame metadata here because
// the service returns the file, not the numbers the run record wants.
const a = $input.first().json;
const [aw, ah] = String(a.ASPECT || '4:5').split(':').map(Number);
const width = Math.max(1, Number(a.VIEWPORT) || 1080);
const height = Math.round(width * (ah || 5) / (aw || 4));
let spec = null;
try { spec = a.SPEC_JSON ? JSON.parse(a.SPEC_JSON) : null; } catch (e) { spec = null; }
const fps = Math.max(1, Number(a.FPS) || 30);
const durationMs = Math.max(1000, Math.min(20000, (spec && spec.motion && Number(spec.motion.durationMs)) || 3000));
const url = ($env.RENDER_URL || '').replace(/\/+$/, '');
return [{ json: Object.assign({}, a, {
  RENDER_URL: url ? url + '/render' : '',
  RENDER_BODY: JSON.stringify({ spec: spec, options: { width: width, height: height, fps: fps } }),
  DURATION_MS: String(durationMs),
  FRAME_COUNT: String(Math.round(fps * durationMs / 1000)),
  WIDTH: String(width),
  HEIGHT: String(height),
}) }];

// Handles render_video's continued error: no binary means that asset carries ERROR
// and the run continues, which is what makes the failure visible instead of silent.
// Binary is read with getBinaryDataBuffer because this instance stores it out of band.
const a = $('build_video').first().json;
const out = $input.first().json || {};
const binMeta = ($input.first().binary && $input.first().binary.data) || null;
const base = { ASSET_TYPE: a.ASSET_TYPE, RENDER_MODE: a.RENDER_MODE || '', FORMAT: a.FORMAT || '',
  STATUS: '', SPEC_JSON: a.SPEC_JSON || '', PROMPT: '', CONTENT_TYPE: '', ERROR: '',
  DURATION_MS: a.DURATION_MS || '', FRAME_COUNT: a.FRAME_COUNT || '',
  WIDTH: a.WIDTH || '', HEIGHT: a.HEIGHT || '', MARKUP: '', IMAGE: '' };
if (!binMeta) {
  const fallback = a.RENDER_URL ? 'render service returned no video' : 'RENDER_URL is not configured';
  const reason = String(out.error || out.message || fallback).slice(0, 500);
  return [{ json: Object.assign({}, base, { STATUS: 'ERROR', ERROR: reason }) }];
}
const mime = binMeta.mimeType || 'video/mp4';
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
return [{ json: Object.assign({}, base, { STATUS: 'RENDERED', CONTENT_TYPE: mime,
  IMAGE: 'data:' + mime + ';base64,' + buffer.toString('base64') }) }];

// Turn the request into the agent's brief and the session request. The brief is the
// caller's CONTENT plus the type's declared frame: duration, size and format. The
// session gets a run-scoped id so a later run cannot overwrite this artifact before
// its caller fetches it. Everything here is data-driven, so a type is retuned from
// the registry (longer, slower, another format) without touching the adapter image.
const a = $input.first().json;
const req = $('normalize_input').first().json;
const safe = (s) => String(s || '').replace(/[^A-Za-z0-9._-]/g, '').slice(0, 40);
const sessionId = (safe(a.ASSET_TYPE) + '-' + safe(req.RUN_ID)) || 'default';
const base = ($env.PI_RENDER_URL || '').replace(/\/+$/, '');
const format = ['mp4', 'gif', 'webp', 'png'].includes(a.FORMAT) ? a.FORMAT : 'mp4';
const [aw, ah] = String(a.ASPECT || '4:5').split(':').map(Number);
const width = Math.max(1, Number(a.VIEWPORT) || 1080);
const height = Math.round(width * (ah || 5) / (aw || 4));
const frames = Math.max(1, Number(a.FRAMES) || 24);
const seconds = Math.max(1, Number(a.DURATION_SECONDS) || Math.round(frames / Math.max(1, Number(a.FPS) || 8)));
// The effective rate for the final GIF: the type budget (frames) spread over the
// declared duration, so a slow 18s clip is 24 samples, not 24 samples per second.
const rate = Math.max(0.1, frames / seconds);
const brief = [
  req.CONTENT,
  '',
  'Render a ' + width + 'x' + height + ' (' + (a.ASPECT || '4:5') + ') composition that runs about ' + seconds + ' seconds.',
  'Animate slowly and deliberately: reveal a few elements in sequence, each held long enough to read, rather than many quick changes. The clip is sampled into a low-frame-rate GIF, so fast or busy motion is lost.',
  'You cannot see images: do not take screenshots and do not write scripts to inspect the layout - rely on `hyperframes lint`.',
  'Run `hyperframes render` in the foreground and let it finish; never background it, because the render aborts the moment its parent shell exits.',
].join('\n') + '\n\n' + $('brand_tokens').first().json.BRAND;
return [{ json: Object.assign({}, a, {
  FORMAT: format,
  FPS: rate, WIDTH: width, HEIGHT: height, FRAMES: frames, DURATION_SECONDS: seconds, RATE: rate,
  SESSION_ID: sessionId,
  AUTHOR_URL: base ? base + '/v1/chat/completions' : '',
  ARTIFACT_URL: base ? base + '/artifacts/' + sessionId + '/out.' + format : '',
  AUTHOR_BODY: JSON.stringify({ messages: [{ role: 'user', content: brief }], session_id: sessionId, format: format, fps: rate, width: width, frames: frames, durationSeconds: seconds }),
}) }];

// The rendered artifact the session returned, as the asset. Read the bytes with
// getBinaryDataBuffer: this instance keeps binaries out of band, so binary.data is a
// reference ("database:<id>"), not the base64. The workflow never sees the agent's
// composition markup, only this file.
const a = $('build_author_brief').first().json;
const out = $input.first().json || {};
const binMeta = ($input.first().binary && $input.first().binary.data) || null;
const base = {
  ASSET_TYPE: a.ASSET_TYPE, RENDER_MODE: a.RENDER_MODE || '', FORMAT: a.FORMAT || '',
  STATUS: '', SPEC_JSON: a.SPEC_JSON || '', PROMPT: '', CONTENT_TYPE: '', ERROR: '',
  DURATION_MS: '', FRAME_COUNT: '', WIDTH: a.WIDTH || '', HEIGHT: a.HEIGHT || '',
  MARKUP: '', IMAGE: '',
};
const describe = (v, fallback) => {
  if (typeof v === 'string' && v) return v;
  if (v && typeof v === 'object' && typeof v.message === 'string') return v.message;
  if (v != null) return JSON.stringify(v);
  return fallback;
};
if (!a.AUTHOR_URL) {
  return [{ json: Object.assign({}, base, { STATUS: 'ERROR', ERROR: 'PI_RENDER_URL is not configured' }) }];
}
if (!binMeta) {
  const reason = describe(out.error || out.message, 'agent authoring returned no artifact').slice(0, 500);
  return [{ json: Object.assign({}, base, { STATUS: 'ERROR', ERROR: reason }) }];
}
const mime = binMeta.mimeType || 'image/gif';
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
return [{ json: Object.assign({}, base, { STATUS: 'RENDERED', CONTENT_TYPE: mime,
  IMAGE: 'data:' + mime + ';base64,' + buffer.toString('base64') }) }];

// The brand tokens, read once from datasets/brand.json (the only copy of the
// brand) and shaped for the three consumers: a short text block for the authoring
// prompts, the photographic art direction for a raster hero, and the raw roles the
// markup templates take.
//
// This node exists so no prompt or template spells a colour or a typeface: a
// surface names a role here and the value travels from brand.json. The build is
// deterministic, so the same brand.json produces the same strings.
const raw = $('download_brand').first().json.output || '{}';
let b;
try {
  b = JSON.parse(raw);
} catch (e) {
  throw new Error('datasets/brand.json is not valid JSON: ' + e.message);
}
const scheme = b.schemes && b.schemes[b.defaultScheme];
if (!scheme) throw new Error('datasets/brand.json has no schemes.' + (b.defaultScheme || ''));
const typo = b.typography || {};
const hex = (v) => String(v || '');
const rgb = (h) => { const s = hex(h).replace('#', ''); return [0, 2, 4].map((i) => parseInt(s.slice(i, i + 2), 16)); };
const hairline = () => {
  const [r, g, bl] = rgb(scheme.ink);
  return 'rgba(' + r + ', ' + g + ', ' + bl + ', ' + Number((b.shape || {}).hairlineAlpha) + ')';
};
const BRAND = [
  'Brand palette (moss on near-black, use only these roles):',
  'background ' + scheme.shell + ', text ' + scheme.ink + ', muted text ' + scheme.inkMuted + ',',
  'accent ' + scheme.accent + ', accent-strong ' + scheme.accentStrong + ', accent-deep ' + scheme.accentDeep + '.',
  'Typefaces: ' + typo.text + ' for text, ' + typo.code + ' for code.',
].join('\n');
return [{ json: {
  BRAND,
  ART_DIRECTION: String((b.photographic || {}).artDirection || ''),
  TEMPLATE: {
    SHELL: scheme.shell,
    INK: scheme.ink,
    INK_MUTED: scheme.inkMuted,
    HAIRLINE: hairline(),
    FONT_TEXT: typo.text,
    FONT_CODE: typo.code,
    RAMP: [scheme.accent, scheme.accentStrong, scheme.accentDeep],
  },
} }];
